# define MAX_STEPS 90
# define MAX_DIST 100.0
# define SURF_DIST 0.01

vec4 loadValue( in ivec2 re )
{
    return texelFetch( iChannel2, re, 0 );
} 
float hash(float v){
    return fract(sin(v * 123.45) * 67.89);
}
float hash2(vec2 v){
    return fract(
        hash(dot(v, vec2(1.23, 4.56))) + 
        hash(dot(v, vec2(2.34, -6.43)))
    );
}
float noise(float v){
    float i = floor(v);

    float v0 = hash(i);
    float v1 = hash(i + 1.);

    return mix(v0, v1, smoothstep(0., 1., fract(v)));
} 

float noise2(vec2 v){
    vec2 i = floor(v);

    float v0 = hash2(i);
    float v1 = hash2(i + vec2(1., 0.));
    float v2 = hash2(i + vec2(0., 1.));
    float v3 = hash2(i + vec2(1., 1.));

    return mix(
        mix(v0, v1, smoothstep(0., 1., fract(v.x))),
        mix(v2, v3, smoothstep(0., 1., fract(v.x))),
        smoothstep(0., 1., fract(v.y))
    );
}

float mountHeight(vec2 pos){
    return texture(iChannel0, (pos + 5.) * .1).r * 4.; 
}

float getDist(vec3 p){
    vec4 s = vec4(0, 1, 6, 1); 
    float plantDist = p.y - mountHeight(p.xz);

    float d = plantDist;
    return d;
}

float rayMarch(vec3 ro, vec3 rd){
    float dO = .0;  
    for(int i = 0;i < MAX_STEPS ; i++){
        vec3 p = ro + rd * dO;
        float ds = min(getDist(p), 1.);
        float scale = mix(0.7, 0.4, smoothstep(2.8, 1.8, length(p.xz)));
        dO += ds * scale; 
        if(dO > MAX_DIST||ds<SURF_DIST){break;}
    }
    return dO;
}

vec3 getNormal(vec3 p){
    float d = getDist(p);
    vec2 e = vec2(0.001, 0);
    vec3 n = d - vec3(
        getDist(p-e.xyy),
        getDist(p-e.yxy),
        getDist(p-e.yyx));

    return normalize(n);
}

float getLight(vec3 p){
    vec3 lightPos = vec3(0, 15, 0);
   // lightPos.xz += vec2(cos(iTime), sin(iTime));
    vec3 l = normalize(lightPos - p);
    vec3 n = getNormal(p);

    float dif = clamp(dot(n, l), 0.0, 1.0);
   // float d = rayMarch(p+n*SURF_DIST,l);
   // if(d<length(lightPos - p)){dif*= 0.1;}
    return dif;
}

vec3 getMountColor(vec2 pos){
    vec3 snow = vec3(.9, .8, .9); 
    vec3 sand = vec3(.5, .43, .35) * (noise2(pos * 211.34) * .2 + .8) * 1.2;
    float rd1 = noise2(pos), rd2 = noise2(pos * 3. + vec2(-1.4, 5.6));
    vec3 rock = texture(iChannel1, (pos + 5.) * .1).rgb;
    float h = mountHeight(pos);
    vec3 c1 = mix(snow, rock, smoothstep(2.3, 1.9, h+rd2*.2));
    return mix(c1, sand, smoothstep(0.7, 0.3, h+rd2*.17));
}

mat2 rot(float rad){
    return mat2(
        cos(rad), -sin(rad), sin(rad), cos(rad)
    );
}

vec3 getSunDir(){
    return normalize(vec3(6., 1., 0.));
}

vec3 fogColor(vec3 rd){
    vec3 sunDir = getSunDir();
    return mix(vec3(.5, .7, .95), vec3(.94, .76, .6), 
        clamp((1. - rd.y) 
        * (dot(normalize(sunDir.xz), normalize(rd.xz)) * .7 + .3), 0., 1.)
    );
}

vec3 atmosphere(vec3 col, vec3 rd, float dist){
    return 
        mix(col, fogColor(rd), smoothstep(1.,  .0, pow(2.718, -dist*.2*dist*.01))) 
        + step(16., dist) *  
            pow(.5 + .5*dot(rd, getSunDir()), 2450.) * vec3(5.4, 2.15, 0.5)  
    ;
}

float heightWater(){
    return loadValue(txSea).r + 0.23;
}

float distWater(vec3 ro, vec3 rd){
    if(rd.y >= -0.01) return MAX_DIST * 10.;
    // water height = 0.23
    float h = heightWater();
    float hDelta = ro.y - h;
    return hDelta / dot(rd, vec3(0., -1., 0.));
}
vec3 waterRefract(vec3 ray, vec3 pos, vec3 n){ 
    return vec3(.0, .15, .3);
}
vec3 waterReflect(vec3 ray, vec3 pos, vec3 n){
    vec3 rd = reflect(ray, n);
    vec3 ro = pos;
    float d = rayMarch(ro, rd);

    vec3 p = ro + rd * d;
    float dif = getLight(p - 2. * SURF_DIST * rd);
    vec3 col = vec3(dif) * getMountColor(p.xz);

    return atmosphere(col, rd, d);
}
vec3 renderWater(vec3 pos, vec3 rd){
    float n1 = 1.0;  
    float n2 = 1.33; 

    vec2 xy = pos.xz;
    float a = noise2(xy + iTime * vec2(-1.23, 0.56)) * 6.28;
    float a2 = noise2(xy * 2.4 + iTime * vec2(-1.23, 0.56)) * 6.28;
    float s = .005;
    vec3 n = vec3((cos(a) + cos(a2)) * s, 1., (sin(a) + sin(a2)) * s);
    n = normalize(n); 
    n = normalize(mix(n, vec3(0., 1., 0.), smoothstep(10., 100., length(xy))));
    //n = vec3(0., 1., 0.);

    float r0 = pow((n1 - n2) / (n1 + n2), 2.0);
    float r = r0 + (1.0 - r0) * pow(1.0 - abs(dot(rd, n)), 5.0);
    float t = 1.0 - r;   

    vec3 c_reflected = waterReflect(rd, pos, n);  
    vec3 c_refracted = waterRefract(rd, pos, n);  

    vec3 c_r = r * c_reflected;
    vec3 c_t = t * c_refracted;
    return c_r + c_t;

}
vec3 render(vec2 uv){
    vec2 mouse = 2.*(iMouse.xy - iResolution.xy * .5) / iResolution.xy;
    if(dot(iMouse.xy, iMouse.xy) < .01) mouse = vec2(0.);
    vec3 col = vec3(0);
    float dh = loadValue(txHeight).x + loadValue(txSea).x;
    float dd = loadValue(txDist).x;
    float md = -loadValue(txDist).y;
    vec3 ro = vec3(md, 0.63 + dh, -7. + dd);
    ro.xz *= rot(-mouse.x * 6.28 * .4 - 1.57);
    float mh = mountHeight(ro.xz);
    ro.y += mh;

    vec3 lookat = vec3(0., 1. + dh + mh + mouse.y * 7. + 23. * mouse.y * mouse.y * mouse.y, 0.);
    vec3 u = vec3(0., 1., 0.);
    vec3 f = normalize(lookat - ro);
    vec3 r = normalize(cross(u, f));
    u = cross(f, r);
    float zoom = 1.;
    if(ctrl) zoom = 1.3;
    vec3 rd = normalize(uv.x * r + uv.y * u + f * zoom);

    float d2 = distWater(ro, rd);
    vec3 pos0 = d2 * rd + ro;
    float h = mountHeight(pos0.xz);
    float d = rayMarch(ro,rd);

    if(d2 < d + pow(max(0., d * .12 - dh - abs(md)+ dd * .1), 12.)){ 
        return atmosphere(renderWater(d2 * rd + ro, rd), rd, d2);
    }
    vec3 p = ro + rd * d;
    float dif = getLight(p - 2. * SURF_DIST * rd);
    col = vec3(dif) * getMountColor(p.xz);

    return atmosphere(col, rd, d);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{ 
    vec2 uv = (fragCoord-0.5*iResolution.xy)/iResolution.y;
    fragColor = vec4(render(uv),1.0);  
}

