    return mix(v0, v1, smoothstep(0., 1., fract(v)));
} 

float noise2(vec2 v){
    vec2 i = floor(v);

    float v0 = hash2(i);
    float v1 = hash2(i + vec2(1., 0.));
    float v2 = hash2(i + vec2(0., 1.));
    float v3 = hash2(i + vec2(1., 1.));

    return mix(
        mix(v0, v1, smoothstep(0., 1., fract(v.x))),
        mix(v2, v3, smoothstep(0., 1., fract(v.x))),
        smoothstep(0., 1., fract(v.y))
    );
}
float mountHeight(vec2 pos){
    return pow(2.718, -dot(pos, pos) * .15) * (
        noise2(pos * 1.1) * 1.23 + 
        noise2(pos * .67 + vec2(3.45, -1.23)) * 4. +
        noise2(pos * 3.67 + vec2(-3.45, 1.23)) * 0.125   
    );
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    uv *= 10.;
    uv -= 5.;
    fragColor = vec4(mountHeight(uv) / 4.,0.0,0.0,1.0);
}

float hash(float v){
    return fract(sin(v * 123.45) * 67.89);
}
float hash2(vec2 v){
    return fract(
        hash(dot(v, vec2(1.23, 4.56))) + 
        hash(dot(v, vec2(2.34, -6.43)))
    );
}
vec2 hash22(vec2 v){
    return vec2(
        hash2(v + vec2(-1.2, 3.4)),
        hash2(v + vec2(2.25, 3.4))
    );
}
vec3 noiseCellular(vec2 uv)
{
    float dist = 30.;
    vec2 bestId;

    for(float x = -1.; x <= 1.; x += 1.){
        for(float y = -1.; y <= 1.; y += 1.){
            vec2 nid = floor(uv) + vec2(x, y);
            vec2 pos = nid + hash22(nid);
            float distNew = length(pos - uv);
            if(distNew < dist){
                dist = distNew;
                bestId = nid;
            }
        }
    }
    float offset = hash2(bestId + vec2(1.2, 3.3));
    float offset2 = hash2(bestId + vec2(1.2, 3.3));
    vec3 col = vec3(0.8, 0.7, 0.6);
    return mix(
        vec3(col.r + offset * .1, col.g + offset2 * .06, col.b), 
        col * .8, pow(dist, 3.86));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy * 100. - 50.;
    vec3 n = noiseCellular(uv);
    fragColor = vec4(n,1.0);
}

const ivec2 txHeight = ivec2(0,0);
const ivec2 txDist = ivec2(1,0);
const ivec2 txSea = ivec2(2,0);

#define keyToggle(ascii)  ( texelFetch(iChannel3,ivec2(ascii,2),0).x > 0.)
#define keyClick(ascii)   ( texelFetch(iChannel3,ivec2(ascii,1),0).x > 0.)
#define keyDown(ascii)    ( texelFetch(iChannel3,ivec2(ascii,0),0).x > 0.)

#define shift             ( texelFetch(iChannel3,ivec2(16,0),0).x  > 0.)
#define ctrl              ( texelFetch(iChannel3,ivec2(17,0),0).x  > 0.)
#define alt               ( texelFetch(iChannel3,ivec2(18,0),0).x  > 0.)

vec4 loadValue( in ivec2 re )
{
    return texelFetch( iChannel2, re, 0 );
}

void storeValue( in ivec2 re, in vec4 va, inout vec4 fragColor, in ivec2 p )
{
    fragColor = (p==re) ? va : fragColor;
}
void storeValue( in ivec4 re, in vec4 va, inout vec4 fragColor, in ivec2 p )
{
    fragColor = ( p.x>=re.x && p.y>=re.y && p.x<=re.z && p.y<=re.w ) ? va : fragColor;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    ivec2 ipx = ivec2(fragCoord-0.5);
    fragColor = vec4(0.0);

    float h = loadValue(txHeight).x;
    float d = loadValue(txDist).x;
    float m = loadValue(txDist).y;
    float hs = loadValue(txSea).x;
    if(keyDown(32)){
        h = h + 0.03;
    }
    if(shift){
        h = max(-0.1, h - 0.03);
    }
    if(keyDown(87)){
        d = d + 0.03;
        d = min(d, 4.);
    }
    else if(keyDown(83)){
        d = d - 0.03;
    }
    if(keyDown(65)){
        m = min(m + 0.03, 1.); 
    }
    else if(keyDown(68)){
        m = max(-1., m - 0.03);
    }
    if(keyDown(81)){
        hs = hs + 0.01; 
    }
    else if(keyDown(69)){
        hs = max(-0.0, hs - 0.01);
    }
    storeValue( txHeight, vec4(h, 0., 0., 0.),   fragColor, ipx );
    storeValue( txDist  , vec4(d, m, 0., 0.),    fragColor, ipx );
    storeValue( txSea   , vec4(hs, 0., 0., 0.),  fragColor, ipx );
}
